// ═══ NON-ASYNC: runs on completing thread ═══
CompletableFuture.supplyAsync(() -> fetchBalance("SAV2001"))  // runs on FJP thread-1
    .thenApply(balance -> balance.multiply(interestRate));      // ALSO runs on FJP thread-1!
// If fetchBalance completes on FJP-thread-1 → thenApply runs on FJP-thread-1
// Fast: no thread switch overhead (~0ns)
// Good for: parseInt, multiply, string format (< 1ms)

// If supplyAsync already completed by the time thenApply is called:
CompletableFuture<String> cf = CompletableFuture.completedFuture("done");
cf.thenApply(s -> s.toUpperCase());  // runs on CALLER thread (main)!
// Already done → no completing thread → caller executes the callback

// ═══ ASYNC: runs on separate pool thread ═══
CompletableFuture.supplyAsync(() -> fetchBalance("SAV2001"))  // FJP thread-1
    .thenApplyAsync(balance -> {
        queryDatabase(balance);  // BLOCKING! 200ms DB call
        return result;
    });
// thenApplyAsync → submitted to ForkJoinPool → runs on FJP thread-2 (different!)
// FJP thread-1 is FREE to complete other futures!

// ═══ ASYNC with custom executor — BEST for blocking ═══
ExecutorService ioPool = Executors.newFixedThreadPool(50);
CompletableFuture.supplyAsync(() -> fetchBalance("SAV2001"))
    .thenApplyAsync(balance -> {
        return callPaymentGateway(balance);  // blocking IO!
    }, ioPool);  // runs on ioPool, NOT ForkJoinPool!
// ForkJoinPool (CPU-bound, small) is NOT polluted by blocking IO!

// ═══ DANGER: blocking in non-async starves ForkJoinPool ═══
// ForkJoinPool.commonPool() has ~(cores-1) threads (e.g., 3 on 4-core)
// If ALL 3 threads are blocked in non-async heavy callbacks:
// → NO other CompletableFuture can make progress!
// → Everything stalls!

for (int i = 0; i < 100; i++) {
    CompletableFuture.supplyAsync(() -> fetchData())
        .thenApply(data -> {
            Thread.sleep(5000);  // BLOCKS FJP thread for 5 seconds!
            return process(data);
        });
}
// 3 FJP threads × 5 seconds each → only 3 of 100 tasks active!
// 97 tasks waiting! Throughput: 0.6 tasks/sec instead of 100!

// FIX:
.thenApplyAsync(data -> {
    Thread.sleep(5000);
    return process(data);
}, ioPool);  // blocking on dedicated pool, FJP free!
