// ─── File: src/test/java/com/bank/asyncstage/AsyncVsSyncStageTest.java ───
package com.bank.asyncstage;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class AsyncVsSyncStageTest {

    // ═══ Non-async: runs on completing thread ═══
    @Test
    void nonAsync_runsOnCompletingThread() throws Exception {
        AtomicReference<String> supplyThread = new AtomicReference<>();
        AtomicReference<String> applyThread = new AtomicReference<>();

        CompletableFuture.supplyAsync(() -> {
            supplyThread.set(Thread.currentThread().getName());
            return "data";
        }).thenApply(d -> {
            applyThread.set(Thread.currentThread().getName());
            return d.toUpperCase();
        }).get();

        // Often same thread (or caller if already done)
        System.out.println("Supply: " + supplyThread.get() + ", Apply: " + applyThread.get());
    }

    // ═══ Async: runs on separate thread ═══
    @Test
    void async_runsOnSeparateThread() throws Exception {
        ExecutorService customPool = Executors.newFixedThreadPool(2);
        AtomicReference<String> asyncThread = new AtomicReference<>();

        CompletableFuture.supplyAsync(() -> "data")
            .thenApplyAsync(d -> {
                asyncThread.set(Thread.currentThread().getName());
                return d.toUpperCase();
            }, customPool)
            .get();

        assertThat(asyncThread.get()).startsWith("pool-");  // custom pool thread!
        customPool.shutdown();
    }

    // ═══ Non-async blocking: starves ForkJoinPool ═══
    @Test
    void nonAsyncBlocking_starvesFJP() throws Exception {
        int parallelism = ForkJoinPool.commonPool().getParallelism();
        System.out.println("FJP parallelism: " + parallelism);

        long start = System.currentTimeMillis();
        // Submit more tasks than FJP threads, each blocks 200ms
        List<CompletableFuture<String>> futures = new java.util.ArrayList<>();
        for (int i = 0; i < parallelism * 3; i++) {
            futures.add(CompletableFuture.supplyAsync(() -> "data")
                .thenApply(d -> {
                    try { Thread.sleep(200); } catch (InterruptedException e) { }
                    return d;
                }));
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long elapsed = System.currentTimeMillis() - start;

        // Should be ~600ms (3 batches × 200ms) instead of ~200ms
        System.out.println("Non-async blocking: " + elapsed + "ms (starved!)");
    }

    // ═══ Async with dedicated pool: no starvation ═══
    @Test
    void asyncWithPool_noStarvation() throws Exception {
        ExecutorService ioPool = Executors.newFixedThreadPool(20);
        int tasks = 20;

        long start = System.currentTimeMillis();
        List<CompletableFuture<String>> futures = new java.util.ArrayList<>();
        for (int i = 0; i < tasks; i++) {
            futures.add(CompletableFuture.supplyAsync(() -> "data")
                .thenApplyAsync(d -> {
                    try { Thread.sleep(200); } catch (InterruptedException e) { }
                    return d;
                }, ioPool));  // dedicated pool!
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(500);  // ~200ms! All parallel on ioPool!
        ioPool.shutdown();
    }
}
